python3 - <<'PY'
from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_sse_validation():
    # Test valid
    try:
        ServerSentEvent(event="test-event", id="test-id", data="hello")
        print("Valid event/id: OK")
    except Exception as e:
        print(f"Valid event/id: FAILED: {e}")

    # Test invalid event (newline)
    try:
        ServerSentEvent(event="test\nevent", id="test-id", data="hello")
        print("Invalid event (newline): FAILED (no exception)")
    except ValidationError as e:
        print(f"Invalid event (newline): OK - {e}")
    except Exception as e:
        print(f"Invalid event (newline): UNEXPECTED EXCEPTION - {type(e)}: {e}")

    # Test invalid event (carriage return)
    try:
        ServerSentEvent(event="test\revent", id="test-id", data="hello")
        print("Invalid event (carriage return): FAILED (no exception)")
    except ValidationError as e:
        print(f"Invalid event (carriage return): OK - {e}")
    except Exception as e:
        print(f"Invalid event (carriage return): UNEXPECTED EXCEPTION - {type(e)}: {e}")

    # Test invalid id (newline)
    try:
        ServerSentEvent(event="test-event", id="test\nid", data="hello")
        print("Invalid id (newline): FAILED (no exception)")
    except ValidationError as e:
        print(f"Invalid id (newline): OK - {e}")
    except Exception as e:
        print(f"Invalid id (newline): UNEXPECTED EXCEPTION - {type(e)}: {e}")

    # Test invalid id (carriage return)
    try:
        ServerSentEvent(event="test-event", id="test\rid", data="hello")
        print("Invalid id (carriage return): FAILED (no exception)")
    except ValidationError as e:
        print(f"Invalid id (carriage return): OK - {e}")
    except Exception as e:
        print(f"Invalid id (carriage return): UNEXPECTED EXCEPTION - {type(e)}: {e}")

    # Test invalid id (null character - should still work)
    try:
        ServerSentEvent(event="test-event", id="test\0id", data="hello")
        print("Invalid id (null): FAILED (no exception)")
    except ValidationError as e:
        print(f"Invalid id (null): OK - {e}")
    except Exception as e:
        print(f"Invalid id (null): UNEXPECTED EXCEPTION - {type(e)}: {e}")

test_sse_validation()
